import java.io.*;
import java.util.*;
public class L{
    public static void main(String[] args) {
        InputStream is = System.in;
        OutputStream os = System.out;
        InputReader ir = new InputReader(is);
        PrintWriter pw = new PrintWriter(os);
        Solver sv = new Solver();
        sv.solve(1, ir, pw);
        pw.flush();pw.close();
    }
    static class Solver {
        class MCMF{
            ArrayList<Edge> g[];
            Edge mat[][];
            int pot[];
            int N, S, T, maxFlow, minCost;
            final int INF = Integer.MAX_VALUE / 100;
            class Edge{
                int to, flow, rev, cost;
                Edge(int a, int b, int c, int d){to=a; flow=b; cost=c; rev=d;}
            }
            void addEdge(int u, int v, int flow, int cost){
                int lu = g[u].size(), lv = g[v].size();
                g[u].add(new Edge(v, flow, cost, lv));
                g[v].add(new Edge(u, 0, -cost, lu));
            }
            void toArray(){
                mat = new Edge[N][];
                for(int i=0;i<N;i++){
                    int sz = g[i].size();
                    mat[i] = new Edge[sz];
                    for(int j=0;j<sz;j++) mat[i][j] = g[i].get(j);
                    g[i].clear();
                }
            }
            MCMF(int n, int s, int t){
                N=n; S=s; T=t; maxFlow=0; minCost=0;
                g = new ArrayList[N];
                pot = new int[N];
                for(int i=0;i<N;i++) g[i]=new ArrayList<>();
            }
            boolean bellmanFord(boolean check){
                pot[0]=0;
                for(int i=0;i<N-1;i++){
                    for(int j=0;j<N;j++){
                        for(Edge e: mat[j]){
                            if(e.flow==0) continue;
                            pot[e.to] = Math.min(pot[e.to], pot[j]+e.cost);
                        }
                    }
                }
                if(check){
                    for(int j=0;j<N;j++){
                        for(Edge e: mat[j]){
                            if(e.flow==0) continue;
                            if(pot[j]+e.cost < pot[e.to]) return false;
                        }
                    }
                }
                return true;
            }
            int q[];
            int vis[];
            int prev[], preve[];
            int dist[];
            boolean simple(){
                q = new int[N];
                vis = new int[N];
                prev = new int[N];
                preve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);
                q[0]=S; dist[0]=0;
                int front=1, back=0;
                while(front!=back){
                    int u = q[back++];
                    if(back==N) back=0;
                    vis[u]=2;
                    for(int i=0;i<mat[u].length;i++){
                        Edge e = mat[u][i];
                        if(e.flow==0) continue;
                        int nd = dist[u] + e.cost;
                        if(nd < dist[e.to]){
                            if(vis[e.to]==0){
                                q[front]=e.to;
                                if(++front==N) front=0;
                            } else if(vis[e.to]==2){
                                if(--back==-1) back+=N;
                                q[back]=e.to;
                            }
                            vis[e.to]=1;
                            preve[e.to]=i; prev[e.to]=u; dist[e.to]=nd;
                        }
                    }
                }
                return vis[T]!=0;
            }
            class Pair{
                int f,s;
                Pair(int a,int b){f=a; s=b;}
            }
            boolean dijkstra(){
                vis = new int[N];
                prev = new int[N];
                preve = new int[N];
                dist = new int[N];
                Arrays.fill(dist, INF);
                PriorityQueue<Pair> pq = new PriorityQueue<>((a,b)->Integer.compare(a.s,b.s));
                pq.add(new Pair(S,0)); dist[0]=0;
                outer: while(!pq.isEmpty()){
                    Pair p = pq.poll();
                    while(dist[p.f] < p.s){
                        if(pq.isEmpty()) break outer;
                        p = pq.poll();
                    }
                    vis[p.f]=2;
                    for(int i=0;i<mat[p.f].length;i++){
                        Edge e = mat[p.f][i];
                        if(e.flow==0) continue;
                        int nd = p.s + (e.cost + pot[p.f] - pot[e.to]);
                        if(nd < dist[e.to]){
                            if(vis[e.to]==2) return false;
                            pq.add(new Pair(e.to, nd));
                            dist[e.to]=nd; prev[e.to]=p.f; preve[e.to]=i;
                            vis[e.to]=1;
                        }
                    }
                }
                return vis[T]!=0;
            }
            int augment(){
                int p=T, min=INF;
                while(p!=0){
                    int pp=prev[p], pe=preve[p];
                    min = Math.min(min, mat[pp][pe].flow);
                    p=pp;
                }
                p=T;
                while(p!=0){
                    int pp=prev[p], pe=preve[p];
                    mat[pp][pe].flow -= min;
                    mat[p][mat[pp][pe].rev].flow += min;
                    p=pp;
                }
                maxFlow += min;
                return min;
            }
            boolean calSimple(){
                while(simple()){
                    minCost += dist[T] * augment();
                }
                return true;
            }
            void updPot(){
                for(int i=0;i<N;i++){
                    if(vis[i]!=0){
                        pot[i] += dist[i] - dist[S];
                    }
                }
            }
            boolean calWithPotential(){
                while(dijkstra()){
                    int min = dist[T] + pot[T] - pot[S];
                    minCost += min * augment();
                    updPot();
                }
                return true;
            }
        }
        int n,m,k,c,d,a[],f[];
        public void solve(int testNumber, InputReader in, PrintWriter out){
            n=in.nextInt(); m=in.nextInt(); k=in.nextInt(); c=in.nextInt(); d=in.nextInt();
