#include <cstdio>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <functional>

using namespace std;

const int INF = 1e9;

struct Edge {
    int to, flow, rev, cost;
    Edge(int a, int b, int c, int d) : to(a), flow(b), cost(c), rev(d) {}
};

struct MCMF {
    int N, S, T, maxFlow, minCost;
    vector<vector<Edge>> g, mat;
    vector<int> pot;

    MCMF(int n, int s, int t) : N(n), S(s), T(t), maxFlow(0), minCost(0), g(n), pot(n, 0) {}

    void addEdge(int u, int v, int flow, int cost) {
        int lu = g[u].size(), lv = g[v].size();
        g[u].emplace_back(v, flow, cost, lv);
        g[v].emplace_back(u, 0, -cost, lu);
    }

    void toArray() {
        mat.resize(N);
        for (int i = 0; i < N; ++i) {
            mat[i] = g[i];
            g[i].clear();
        }
    }

    bool bellmanFord(bool check) {
        pot[0] = 0;
        for (int i = 0; i < N - 1; ++i) {
            for (int j = 0; j < N; ++j) {
                for (const Edge& e : mat[j]) {
                    if (e.flow == 0) continue;
                    if (pot[j] + e.cost < pot[e.to]) {
                        pot[e.to] = pot[j] + e.cost;
                    }
                }
            }
        }
        if (check) {
            for (int j = 0; j < N; ++j) {
                for (const Edge& e : mat[j]) {
                    if (e.flow == 0) continue;
                    if (pot[j] + e.cost < pot[e.to]) return false;
                }
            }
        }
        return true;
    }

    bool simple() {
        vector<int> q(N), vis(N, 0), prev(N), preve(N), dist(N, INF);
        q[0] = S;
        dist[0] = 0;
        int front = 1, back = 0;
        while (front != back) {
            int u = q[back++];
            if (back == N) back = 0;
            vis[u] = 2;
            for (int i = 0; i < (int)mat[u].size(); ++i) {
                const Edge& e = mat[u][i];
                if (e.flow == 0) continue;
                int nd = dist[u] + e.cost;
                if (nd < dist[e.to]) {
                    if (vis[e.to] == 0) {
                        q[front] = e.to;
                        if (++front == N) front = 0;
                    } else if (vis[e.to] == 2) {
                        if (--back == -1) back += N;
                        q[back] = e.to;
                    }
                    vis[e.to] = 1;
                    preve[e.to] = i;
                    prev[e.to] = u;
                    dist[e.to] = nd;
                }
            }
        }
        return vis[T] != 0;
    }

    int augment() {
        int p = T, minFlow = INF;
        while (p != 0) {
            int pp = prev[p], pe = preve[p];
            minFlow = min(minFlow, mat[pp][pe].flow);
            p = pp;
        }
        p = T;
        while (p != 0) {
            int pp = prev[p], pe = preve[p];
            mat[pp][pe].flow -= minFlow;
            mat[p][mat[pp][pe].rev].flow += minFlow;
            p = pp;
        }
        maxFlow += minFlow;
        return minFlow;
    }

    bool calSimple() {
        while (simple()) {
            minCost += dist[T] * augment();
        }
        return true;
    }

    struct ComparePairSecond {
        bool operator()(const pair<int,int>& a, const pair<int,int>& b) const {
            return a.second > b.second;
        }
    };

    bool dijkstra() {
        vector<int> vis(N, 0), prev(N), preve(N), dist(N, INF);
        priority_queue<pair<int,int>, vector<pair<int,int>>, ComparePairSecond> pq;
        pq.push({S, 0});
        dist[0] = 0;
        while (!pq.empty()) {
            auto p = pq.top(); pq.pop();
            while (dist[p.first] < p.second) {
                if (pq.empty()) break;
                p = pq.top(); pq.pop();
            }
            vis[p.first] = 2;
            for (int i = 0; i < (int)mat[p.first].size(); ++i) {
                const Edge& e = mat[p.first][i];
                if (e.flow == 0) continue;
                int nd = p.second + (e.cost + pot[p.first] - pot[e.to]);
                if (nd < dist[e.to]) {
                    if (vis[e.to] == 2) return false;
                    pq.push({e.to, nd});
                    dist[e.to] = nd;
                    prev[e.to] = p.first;
                    preve[e.to] = i;
                    vis[e.to] = 1;
                }
            }
        }
        return vis[T] != 0;
    }

    void updPot() {
        for (int i = 0; i < N; ++i) {
            if (vis[i] != 0) {
                pot[i] += dist[i] - dist[S];
            }
        }
    }

    bool calWithPotential() {
        while (dijkstra()) {
            int minCostAdd = dist[T] + pot[T] - pot[S];
            minCost += minCostAdd * augment();
            updPot();
        }
        return true;
    }
};

struct Solver {
    int n, m, k, c, d;
    vector<int> a, f;

    void solve(int testNumber, InputReader& in, FILE* out) {
        n = in.nextInt(); m = in.nextInt(); k = in.nextInt(); c = in.nextInt(); d = in.nextInt();
        int maxl = n + k;
        int T = n * maxl + 1;
        MCMF ans(T + 1, 0, T);
        a.resize(k + 1);
        f.assign(n + 1, 0);
        for (int i = 1; i <= k; ++i) {
            a[i] = in.nextInt();
            f[a[i]]++;
        }
        for (int i = 1; i <= n; ++i) {
            if (f[i] == 0) continue;
            ans.addEdge(0, i, f[i], 0);
        }
        for (int i = 2; i <= n; ++i) {
            for (int l = 0; l < maxl - 1; ++l) {
                ans.addEdge(l * n + i, (l + 1) * n + i, k, c);
            }
        }
        for (int i = 1; i <= m; ++i) {
            int a = in.nextInt(), b = in.nextInt();
            for (int l = 0; l < maxl - 1; ++l) {
                for (int p = 1; p <= k; ++p) {
                    if (a != 1)
                        ans.addEdge(n * l + a, n * (l + 1) + b, 1, d * (2 * p - 1) + c);
                    if (b != 1)
                        ans.addEdge(n * l + b, n * (l + 1) + a, 1, d * (2 * p - 1) + c);
                }
            }
        }
        for (int l = 1; l < maxl; ++l) {
            ans.addEdge(l * n + 1, T, k, 0);
        }
        ans.toArray();
        ans.calSimple();
        if (ans.maxFlow != k) {
            fprintf(out, "BUG\n");
        } else {
            fprintf(out, "%d\n", ans.minCost);
        }
    }
};

struct InputReader {
    int nextInt() {
        int x;
        scanf("%d", &x);
        return x;
    }
    long long nextLong() {
        long long x;
        scanf("%lld", &x);
        return x;
    }
    double nextDouble() {
        double x;
        scanf("%lf", &x);
        return x;
    }
};

int main() {
    InputReader ir;
    Solver sv;
    sv.solve(1, ir, stdout);
    return 0;
}
